!function(){"use strict";const t={elements:{countdown:".cariera-countdown",items:null},init(){this.elements.items=document.querySelectorAll(this.elements.countdown),this.elements.items.length&&this.elements.items.forEach(t=>this.initCountdown(t))},initCountdown(t){const e=t.dataset.countdown;if(!e)return;const n=new Date(e).getTime();if(isNaN(n))return void console.warn("CarieraCountdown: Invalid date value on element:",t);const s=this.getLabels(t),i=()=>{const e=this.getRemaining(n);this.render(t,e,s),e.total<=0&&clearInterval(o)},o=setInterval(i,1e3);i()},getLabels(t){return{days:t.dataset.days||"Days",hours:t.dataset.hours||"Hours",mins:t.dataset.mins||"Minutes",secs:t.dataset.secs||"Seconds"}},getRemaining(t){const e=Math.max(0,t-Date.now());return{total:e,days:Math.floor(e/864e5),hours:Math.floor(e/36e5%24),mins:Math.floor(e/6e4%60),secs:Math.floor(e/1e3%60)}},render(t,e,n){t.innerHTML=this.unit(e.days,n.days)+this.unit(e.hours,n.hours)+this.unit(e.mins,n.mins)+this.unit(e.secs,n.secs)},unit(t,e){return`<div><span class="value">${t}</span><h6>${e}</h6></div>`}};document.addEventListener("DOMContentLoaded",()=>t.init()),window.addEventListener("elementor/frontend/init",()=>{elementorFrontend.hooks.addAction("frontend/element_ready/count_down.default",()=>t.init())})}();